# Analyzing the pattern from demos:
# - Input colors extracted in reading order become overlay layers
# - Output has all overlay colors arranged in diamond-like layers
# - Demo 1: [4, 1, 6] -> output has 4-layer, 1-layer, 6-layer
# - Demo 2: [7, 2, 1, 3] -> output has 7-layer, 2-layer, 1-layer, 3-layer

# Test input has colors [1, 2, 8, 7, 3] (reading down columns)
# Expected pattern: 5 diamond layers stacked

input_colors = [1, 2, 8, 7, 3]

# Build output grid with diamond layers
output = [[0 for _ in range(15)] for _ in range(18)]

# Even-layer: colors [2, 8] - stacked at rows 4-7
for i, color in enumerate([2, 8]):
    start_row = 4 + i * 3
    for r in range(3):
        row_idx = start_row + r
        for c in range(7):
            if r == 0:
                col_idx = 3 + c  # top row: full width
            elif r == 1:
                col_idx = 3 if c == 2 else -1  # middle row: 1x3
            else:
                col_idx = 1 + c  # bottom row: full width
            if 0 <= col_idx < 15:
                output[row_idx][col_idx] = color

# Odd-layer: colors [1, 7, 3] - stacked at rows 10-16
for i, color in enumerate([1, 7, 3]):
    start_row = 11 + i * 3
    for r in range(4):
        row_idx = start_row + r
        for c in range(7):
            if r == 0:
                col_idx = 3 + c  # top row: 2x3
            elif r == 1:
                col_idx = 2 + c  # 2x3
            elif r == 2:
                col_idx = 2 if c == 1 else 3 if c == 2 else 4  # middle
            else:
                col_idx = 1 + c  # bottom: full width
            if 0 <= col_idx < 15:
                output[row_idx][col_idx] = color

print('Output grid with diamond layers:')
for row in output:
    print(' '.join(map(str, row)))

